    rail_cols = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= h - 2]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] == 0:
            g[r][c] = 1

    for r, c in motifs:
        # Extend the marker's center row and column through empty cells.
        for j in range(w):
            paint(r, j)
        for i in range(h):
            paint(i, c)

        # At each crossing with a rail, reproduce the marker's border in 1.
        for rr in rail_rows:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
