        # retaining the crossing cell itself and any 3-colored marker cells.
        for rr, cc in [(r, x) for x in rail_cols] + [(x, c) for x in rail_rows]:
            for i in range(max(0, rr - 1), min(h, rr + 2)):
                for j in range(max(0, cc - 1), min(w, cc + 2)):
                    if (i, j) != (rr, cc) and g[i][j] in (0, 2):
                        g[i][j] = 1

    return g
